Yes, I can help you with that. Here's a Swift program that calculates the Levenshtein distance between the words 'dog' and 'cat':
```swift
func levenshteinDistance(s: String, t: String) -> Int {
    let n = s.count
    let m = t.count
    if n == 0 {
        return m
    }
    if m == 0 {
        return n
    }
    var d = Array(repeating: Array(repeating: 0, count: m + 1), count: n + 1)
    for i in 0...n {
        d[i][0] = i
    }
    for j in 0...m {
        d[0][j] = j
    }
    for i in 1...n {
        for j in 1...m {
            let cost = s[s.index(s.startIndex, offsetBy: i - 1)] == t[t.index(t.startIndex, offsetBy: j - 1)] ? 0 : 1
            d[i][j] = Swift.min(
                d[i - 1][j] + 1,
                d[i][j - 1] + 1,
                d[i - 1][j - 1] + cost
            )
        }
    }
    return d[n][m]
}
let distance = levenshteinDistance(s: "dog", t: "cat")
print("The Levenshtein distance between 'dog' and 'cat' is \(distance).")
```
