    Console.WriteLine("Task will start in " + delay.TotalMinutes + " minutes");
    Task.Delay(delay).Wait();
    Console.WriteLine("Starting task: " + task);
    Task.Delay(time * 60000).Wait();
    Console.WriteLine("Task completed!");
  }
}
This code prompts the user for a task to complete, how long it will take, and when they want to start. It then calculates the delay until the task should start, waits that long, completes the task, and outputs a completion message. By breaking down tasks into manageable chunks and scheduling them, the individual may be able to overcome their procrastination and establish a productive routine.

